effect.shader:
const float PI = 3.14159265;
const vec3 LUMA = vec3(0.2126, 0.7152, 0.0722);

// 16 passos por direção. Mais que isso não muda o que se vê e custa linear; com
// muito menos, o hexágono vira uma fileira de fantasmas em vez de um borrão.
const int PASSOS = 16;

vec2 paraUv(vec2 v) { return vec2(v.x / max(acAspect, 1e-4), v.y); }

vec2 direcao(float graus) {
    float a = (graus + rotation) * PI / 180.0;
    return vec2(sin(a), cos(a));
}

// A separação de profundidade (0..1) que já conta como "totalmente fora de
// foco" — mesma constante e mesmo raciocínio de `depth-map.xml`: sem isto, só
// uma separação extrema entre assunto e fundo chegaria perto do raio cheio.
const float FAIXA_DE_QUEDA = 0.3;

/**
 * O raio naquele ponto, já considerando o mapa de profundidade.
 *
 * O mapa entra como MULTIPLICADOR e não como substituto: assim o slider de raio
 * continua sendo o controle mestre, e o mapa só decide onde ele vale.
 *
 * `profundidade - focusDistance` é o MESMO termo de `depth-map.xml`: o plano
 * escolhido em `focusDistance` fica nítido, e quem está mais longe dele (pra
 * qualquer lado) desfoca proporcionalmente — não é mais "claro borra, escuro
 * não", que ignorava qual profundidade a pessoa queria manter nítida.
 */
float raioEm(vec2 uv) {
    if (useMap <= 0.0) return radius;
    float profundidade = dot(texture(focusMap, uv).rgb, LUMA);
    float queda = clamp(abs(profundidade - focusDistance) / FAIXA_DE_QUEDA, 0.0, 1.0);
    return radius * mix(1.0, queda, useMap);
}

/** A cor da fonte já preparada para somar: realçada e em energia. */
vec4 fonteEm(vec2 uv) {
    vec4 c = texture(inputImg, uv);

    // Realce só do que já é claro. Espalhar tudo igualmente clarearia a imagem
    // inteira em vez de acender as luzes.
    float luz = dot(c.rgb, LUMA);

    // A borda de cima passa de 1,0 quando o corte está alto, e isso é proposital:
    // apertar as duas bordas no mesmo valor faria `smoothstep` dividir por zero, o
    // que a especificação não define. Com o corte no máximo, nada acende — que é
    // exatamente o que o controle promete.
    float acima = smoothstep(cut, cut + 0.25, luz);
    vec3 realcada = c.rgb * (1.0 + boost * acima);

    return vec4(pow(max(realcada, 0.0), vec3(energy)), c.a);
}

/**
 * Borra em UMA direção, somando em energia.
 *
 * O alfa entra multiplicando a cor e sai dividindo: pixel transparente não tem
 * cor que signifique alguma coisa, e misturá-la puxaria a borda para preto.
 */
vec4 borrarDirecao(sampler2D tex, vec2 uv, vec2 dir, float raio, bool jaEmEnergia) {
    if (raio <= 0.0) {
        return jaEmEnergia ? texture(tex, uv) : fonteEm(uv);
    }

    vec2 passo = paraUv(dir) * (raio / float(PASSOS));
    vec3 soma = vec3(0.0);
    float peso = 0.0;

    for (int i = 0; i <= PASSOS; i++) {
        vec2 p = uv + passo * float(i);
        vec4 c = jaEmEnergia ? texture(tex, p) : fonteEm(p);
        soma += c.rgb * c.a;
        peso += c.a;
    }

    return vec4(soma / max(peso, 1e-4), peso / float(PASSOS + 1));
}

void main() {
    float raio = raioEm(acScreenNorm);

    // As três direções do diafragma, a 120° uma da outra: é a menor quantidade
    // de direções que fecha um polígono convexo.
    vec2 cima = direcao(0.0);
    vec2 baixoEsq = direcao(120.0);
    vec2 baixoDir = direcao(240.0);

    if (acPass == 0) {
        fragColor = borrarDirecao(inputImg, acScreenNorm, cima, raio, false);
        return;
    }
    if (acPass == 1) {
        fragColor = borrarDirecao(inputImg, acScreenNorm, baixoEsq, raio, false);
        return;
    }
    if (acPass == 2) {
        fragColor = borrarDirecao(bufV, acScreenNorm, baixoEsq, raio, true);
        return;
    }

    // Último passe: o segundo losango sai de V+DL, e a média dos dois losangos
    // é o hexágono.
    vec4 original = texture(inputImg, acScreenNorm);

    vec2 passo = paraUv(baixoDir) * (raio / float(PASSOS));
    vec3 soma = vec3(0.0);
    float peso = 0.0;
    for (int i = 0; i <= PASSOS; i++) {
        vec2 p = acScreenNorm + passo * float(i);
        vec4 v = texture(bufV, p);
        vec4 dl = texture(bufDL, p);
        vec3 juntos = (v.rgb * v.a + dl.rgb * dl.a) * 0.5;
        float a = (v.a + dl.a) * 0.5;
        soma += juntos;
        peso += a;
    }
    vec4 losango2 = vec4(soma / max(peso, 1e-4), peso / float(PASSOS + 1));
    vec4 losango1 = texture(bufR1, acScreenNorm);

    vec3 energiaFinal = (losango1.rgb + losango2.rgb) * 0.5;
    float alfa = (losango1.a + losango2.a) * 0.5;

    // Volta da energia para a cor guardada. Sem esta raiz, tudo sairia lavado.
    vec3 cor = pow(max(energiaFinal, 0.0), vec3(1.0 / max(energy, 0.001)));

    // Raio zero tem que devolver a imagem intacta, e não uma versão que passou
    // por potência e raiz — as duas juntas não são exatamente a identidade.
    float quanto = smoothstep(0.0, 0.002, raio);
    fragColor = mix(original, vec4(cor, min(alfa, 1.0) * original.a + (1.0 - original.a) * alfa), quanto);
}
